/**
 * Chunked serializer for session-continuity payloads.
 *
 * A single `JSON.stringify` of a very large session (e.g. a restored
 * 19k-message thread) builds one huge contiguous string, and the legacy
 * envelope then stringifies that string a second time to escape it. Both
 * passes can exceed what V8 can allocate and abort the main process.
 *
 * This module produces the exact same bytes as
 * `JSON.stringify({ encrypted: false, data: JSON.stringify(value) })`
 * but as a list of bounded chunks, so no step materialises the whole
 * payload as one string. Writers stream the chunks to disk in order.
 */

/** A serialized payload: either one string or ordered chunks to concatenate. */
export type ContinuityPayload = string | readonly string[];

/** Target size (UTF-16 code units) at which pending tokens are flushed into a chunk. */
export const CONTINUITY_PAYLOAD_CHUNK_CHARS = 1 << 20;

class ChunkSink {
  readonly chunks: string[] = [];
  private pending: string[] = [];
  private pendingLength = 0;

  constructor(private readonly chunkChars: number) {}

  push(token: string): void {
    this.pending.push(token);
    this.pendingLength += token.length;
    if (this.pendingLength >= this.chunkChars) this.flush();
  }

  flush(): void {
    if (this.pending.length === 0) return;
    this.chunks.push(this.pending.join(''));
    this.pending = [];
    this.pendingLength = 0;
  }
}

/**
 * Append the JSON text of `value` to `sink`, mirroring `JSON.stringify`
 * semantics (toJSON, boxed primitives, omitted undefined/function/symbol
 * members, `null` for such array elements, circular-structure TypeError).
 * Returns false when the value is not serializable (would be omitted).
 *
 * Chunk boundaries only ever fall between whole tokens, and every token is
 * well-formed `JSON.stringify` output, so a chunk never splits a surrogate
 * pair. That keeps per-chunk string escaping identical to escaping the whole.
 */
function writeValue(
  key: string,
  input: unknown,
  sink: ChunkSink,
  stack: Set<object>,
): boolean {
  let value = input;
  if (value !== null && (typeof value === 'object' || typeof value === 'bigint')) {
    const toJSON = (value as { toJSON?: unknown }).toJSON;
    if (typeof toJSON === 'function') value = toJSON.call(value, key);
  }

  if (value === null || typeof value !== 'object') {
    if (value === undefined || typeof value === 'function' || typeof value === 'symbol') return false;
    // Primitives (string, number, boolean, bigint→throws) exactly as JSON.stringify.
    sink.push(JSON.stringify(value));
    return true;
  }

  if (value instanceof Number || value instanceof String || value instanceof Boolean) {
    sink.push(JSON.stringify(value));
    return true;
  }

  if (stack.has(value)) throw new TypeError('Converting circular structure to JSON');
  stack.add(value);
  try {
    if (Array.isArray(value)) {
      sink.push('[');
      for (let index = 0; index < value.length; index++) {
        if (index > 0) sink.push(',');
        if (!writeValue(String(index), value[index], sink, stack)) sink.push('null');
      }
      sink.push(']');
      return true;
    }

    const record = value as Record<string, unknown>;
    sink.push('{');
    let first = true;
    for (const property of Object.keys(record)) {
      const member = record[property];
      if (member === undefined || typeof member === 'function' || typeof member === 'symbol') continue;
      sink.push(first ? `${JSON.stringify(property)}:` : `,${JSON.stringify(property)}:`);
      first = false;
      if (!writeValue(property, member, sink, stack)) {
        // Only reachable when toJSON() returned an unserializable value; JSON.stringify
        // drops the member entirely, so retract the key we optimistically wrote.
        throw new UnserializableMemberError();
      }
    }
    sink.push('}');
    return true;
  } finally {
    stack.delete(value);
  }
}

class UnserializableMemberError extends Error {}

/**
 * Serialize `value` to JSON chunks equivalent to `JSON.stringify(value)`.
 * Returns `undefined` when `JSON.stringify(value)` would return `undefined`.
 */
export function stringifyJsonChunks(
  value: unknown,
  chunkChars = CONTINUITY_PAYLOAD_CHUNK_CHARS,
): string[] | undefined {
  const sink = new ChunkSink(chunkChars);
  try {
    if (!writeValue('', value, sink, new Set<object>())) return undefined;
  } catch (error) {
    if (!(error instanceof UnserializableMemberError)) throw error;
    // Rare toJSON edge case: fall back to the engine for exact semantics.
    const json = JSON.stringify(value) as string | undefined;
    return json === undefined ? undefined : [json];
  }
  sink.flush();
  return sink.chunks;
}

/**
 * Build the plaintext `{ encrypted: false, data: "<json>" }` envelope as
 * chunks. Byte-identical to
 * `JSON.stringify({ encrypted: false, data: JSON.stringify(value) })`.
 */
export function serializePlainEnvelopeChunks(
  value: unknown,
  chunkChars = CONTINUITY_PAYLOAD_CHUNK_CHARS,
): string[] {
  const jsonChunks = stringifyJsonChunks(value, chunkChars);
  if (jsonChunks === undefined) return [JSON.stringify({ encrypted: false, data: undefined })];
  const envelope = ['{"encrypted":false,"data":"'];
  for (const chunk of jsonChunks) envelope.push(JSON.stringify(chunk).slice(1, -1));
  envelope.push('"}');
  return envelope;
}

/** Join a payload into one string. Only for consumers that cannot stream (e.g. OS encryption). */
export function joinContinuityPayload(payload: ContinuityPayload): string {
  return typeof payload === 'string' ? payload : payload.join('');
}

export function continuityPayloadChunks(payload: ContinuityPayload): readonly string[] {
  return typeof payload === 'string' ? [payload] : payload;
}

