/**
 * Longest text treated as a standalone limit notice. Real notices are a line
 * or two; a longer final answer is the model's own work even when it quotes a
 * notice somewhere inside it.
 */
const PROVIDER_LIMIT_EXIT_MAX_CHARS = 600;

/** Leading decoration and labels a CLI may print before the notice itself. */
const PROVIDER_LIMIT_EXIT_PREFIX_RE =
  /^[\s>*_`"'[(⎿●•·-]*(?:(?:(?:api\s+)?error(?:\s+\d{3})?|claude(?:\s+ai)?|anthropic|codex|openai|gemini|(?:github\s+)?copilot|cursor)\s*[:\-–—]?\s*)*/i;

const LIMIT_NOUN = String.raw`(?:limits?|quota|cap|credits|allowance|budget|capacity)`;

/**
 * Notice shapes for an *ended* run, each anchored to the start of the message
 * (after {@link PROVIDER_LIMIT_EXIT_PREFIX_RE}). Covers usage, session and
 * spend/budget limits across the Claude, Codex, Gemini, Copilot and Cursor
 * wording. Bare mentions ("resets at 6pm", "too many requests", "quota") are
 * deliberately absent.
 */
export const PROVIDER_LIMIT_EXIT_PATTERNS: readonly RegExp[] = [
  // "You've hit your limit · resets 3pm", "You have exceeded your monthly quota",
  // "You've reached your spend limit", "You exceeded your current quota",
  // "You have exhausted your capacity on this model", "You've run out of credits"
  new RegExp(
    String.raw`^you(?:'ve|’ve|\s+have)?\s+(?:hit|reached|exceeded|exhausted|used\s+up|run\s+out\s+of)\s+(?:all\s+of\s+)?(?:your|the)?\s*(?:[\w-]+\s+){0,3}${LIMIT_NOUN}\b`,
    'i',
  ),
  // "You're out of extra usage · resets 3pm", "You are out of credits"
  /^you(?:'re|’re|\s+are)\s+out\s+of\s+(?:[\w-]+\s+){0,2}(?:usage|credits|quota)\b/i,
  // "Claude AI usage limit reached|…", "5-hour limit reached", "Spend limit
  // reached", "Monthly spending cap exceeded", "Quota exceeded for quota metric …"
  new RegExp(String.raw`^(?:[\w-]+\s+){0,3}${LIMIT_NOUN}\s+(?:has\s+been\s+)?(?:reached|exceeded|exhausted)\b`, 'i'),
  // "Your organization has reached its monthly spend limit"
  new RegExp(
    String.raw`^(?:your|the)\s+(?:organization|organisation|org|workspace|account|team|enterprise)\s+has\s+(?:hit|reached|exceeded|exhausted)\s+(?:its|their|your|the)\s+(?:[\w-]+\s+){0,3}${LIMIT_NOUN}\b`,
    'i',
  ),
  // "Your credit balance is too low to access the Anthropic API"
  /^(?:your\s+)?credit\s+balance\s+is\s+too\s+low\b/i,
];

/**
 * True when an automation's final output *is* a provider usage/spend-limit
 * notice, meaning the run stopped on the limit rather than finishing its task.
 *
 * Stricter than {@link isProviderNotice}: a misclassified run is recorded as
 * failed, so ordinary output that merely mentions a reset time, quota wording
 * or "too many requests" must not match. The notice has to open the message
 * and the message has to be notice-sized.
 */
export function isProviderLimitExitNotice(text: string | null | undefined): boolean {
  const trimmed = text?.trim();
  if (!trimmed || trimmed.length > PROVIDER_LIMIT_EXIT_MAX_CHARS) return false;
  const body = trimmed.replace(PROVIDER_LIMIT_EXIT_PREFIX_RE, '');
  return PROVIDER_LIMIT_EXIT_PATTERNS.some((re) => re.test(body));
}

