/**
 * A raw app-server update can carry `primary` and `rateLimitReachedType` too
 * (with `resetsAt` in seconds and a raw `credits` block), so only the parsed
 * shape's own `creditsAvailable` field, without a raw `credits` block, marks
 * an already-parsed snapshot.
 */
function isParsedCodexSnapshot(value: unknown): value is CodexRateLimitSnapshot {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const keys: readonly string[] = ['primary', 'secondary', 'planType', 'rateLimitReachedType', 'creditsAvailable'];
  return keys.every((key) => key in value) && !('credits' in value);
}

