/**
 * Create-time initial prompt (the lifecycle dispatches it straight to the
 * adapter): records it as the turn a provider-limit park re-sends, then
 * consults the known-limit ledger exactly like sendInput(). Returns true when
 * a known limit took the turn and the prompt must stay undelivered.
 */
holdInitialPromptOnKnownProviderLimit(instanceId: string, prompt: string): boolean {
  const instance = this.deps.getInstance(instanceId);
  if (!instance) return false;
  this.overflow.rememberLastSent(instanceId, { message: prompt });
  return shouldSkipKnownProviderLimitDispatch(this.deps.checkKnownProviderLimitBeforeSend, {
    instanceId,
    provider: instance.provider,
    model: instance.currentModel ?? null,
    prompt,
  });
}

/** Routes a failed create-time initial prompt through the provider-limit funnel used by later turns. */
parkInitialPromptOnProviderLimit(instanceId: string, error: unknown): boolean {
  const instance = this.deps.getInstance(instanceId);
  const adapter = this.deps.getAdapter(instanceId);
  if (!instance || !adapter) return false;
  const errorMessage = error instanceof Error ? error.message : String(error);
  if (!this.tryParkOnProviderLimit(instanceId, instance, adapter, error, errorMessage)) return false;
  this.deps.onToolStateChange?.(instanceId, 'idle');
  this.deps.queueUpdate(instanceId, instance.status, instance.contextUsage);
  return true;
}

