private mountedSize: WidgetSize | null = null;
private resizeObserver: ResizeObserver | null = null;
private destroyed = false;

ngAfterViewInit(): void {
  void this.mount();
  const el = this.host()?.nativeElement;
  if (typeof ResizeObserver !== 'undefined' && el) {
    this.resizeObserver = new ResizeObserver(() => this.onResize());
    this.resizeObserver.observe(el);
  }
}

ngOnDestroy(): void {
  this.destroyed = true;
  this.resizeObserver?.disconnect();
  this.resizeObserver = null;
  this.removeWidget();
}

/**
 * Turnstile cannot resize a rendered widget, so redraw it when the column crosses the
 * compact/normal line. Redrawing discards a passed check, so same-side changes are ignored.
 */
private onResize(): void {
  const el = this.host()?.nativeElement;
  if (this.destroyed || !this.widgetId || !el || el.clientWidth === 0) return;
  if (widgetSize(el.clientWidth) === this.mountedSize) return;
  this.token.set('');
  this.tokenChange.emit('');
  this.removeWidget();
  void this.mount();
}

