import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { load } from 'js-yaml';

const workflow = load(readFileSync('.github/workflows/model-catalog-watch.yml', 'utf8'));
const steps = workflow.jobs.watch.steps;
const refreshIndex = steps.findIndex(step => step.id === 'refresh');
const prelude = `
npm() { return "$REFRESH_STATUS"; }
git() {
  if [[ "$*" == *--quiet* ]]; then return "$DIFF_STATUS"; fi
  echo '+generated snapshot change'
}
gh() {
  if [[ "$2" == list ]]; then
    echo "$EXISTING_ISSUE"
    return "$LIST_STATUS"
  fi
  echo "$2" >> "$OPERATION_FILE"
  cat "\${@: -1}" > "$BODY_FILE"
  return "$WRITE_STATUS"
}
`;
const cases = [
  { name: 'drift creates issue', diff: 1, existing: '', operation: 'create', success: true },
  { name: 'drift updates issue', diff: 1, existing: '42', operation: 'edit', success: true },
  { name: 'no drift skips issue', diff: 0, existing: '', success: true },
  { name: 'refresh failure stays red', diff: 1, refresh: 7, success: false },
  { name: 'issue lookup failure stays red', diff: 1, list: 8, success: false },
  { name: 'issue creation failure stays red', diff: 1, write: 9, existing: '', success: false },
  { name: 'issue update failure stays red', diff: 1, write: 9, existing: '42', success: false },
];
for (const scenario of cases) {
  const dir = mkdtempSync(resolve('_scratch/catalog-watch-'));
  const output = resolve(dir, 'output');
  const summary = resolve(dir, 'summary');
  const body = resolve(dir, 'body');
  const operation = resolve(dir, 'operation');
  writeFileSync(output, '');
  writeFileSync(summary, '');
  const env = {
    ...process.env, GITHUB_OUTPUT: output, GITHUB_STEP_SUMMARY: summary,
    GITHUB_SERVER_URL: 'https://example.invalid', GITHUB_REPOSITORY: 'example/repo', GITHUB_RUN_ID: '123',
    TMPDIR: dir, BODY_FILE: body, OPERATION_FILE: operation,
    REFRESH_STATUS: String(scenario.refresh ?? 0), DIFF_STATUS: String(scenario.diff),
    LIST_STATUS: String(scenario.list ?? 0), WRITE_STATUS: String(scenario.write ?? 0),
    EXISTING_ISSUE: scenario.existing ?? '',
  };
  let status = 0;
  for (const step of steps.slice(refreshIndex)) {
    if (step.if && !readFileSync(output, 'utf8').includes('drift=true')) continue;
    const result = spawnSync('bash', ['--noprofile', '--norc', '-e', '-o', 'pipefail', '-c', prelude + step.run], { env, encoding: 'utf8' });
    assert.equal(result.error, undefined);
    status = result.status;
    if (status !== 0) break;
  }
  assert.equal(status === 0, scenario.success, `${scenario.name}: exit ${status}`);
  if (scenario.operation) {
    assert.equal(readFileSync(operation, 'utf8').trim(), scenario.operation);
    const issueBody = readFileSync(body, 'utf8');
    for (const expected of ['npm run sync:model-catalog', 'PROVIDER_MODEL_REPLACEMENTS', 'Generated snapshot diff', '+generated snapshot change', 'https://example.invalid/example/repo/actions/runs/123']) {
      assert.ok(issueBody.includes(expected), `${scenario.name}: missing ${expected}`);
    }
    assert.ok(readFileSync(summary, 'utf8').includes('+generated snapshot change'));
  }
  if (scenario.diff === 0 || scenario.refresh) {
    assert.equal(readFileSync(output, 'utf8'), scenario.refresh ? '' : 'drift=false\n');
    assert.throws(() => readFileSync(operation));
  }
  console.log(`PASS ${scenario.name} (exit ${status})`);
  rmSync(dir, { recursive: true, force: true });
}

